    def collatz_sequence(x):
        while x != 1:
            yield x
            if x % 2 == 0:
                x //= 2
            else:
                x = 3 * x + 1
        yield x

    # Generate the Collatz sequence and filter out the odd numbers
    odd_numbers = [num for num in collatz_sequence(n) if num % 2 != 0]

