import re

def solve(s):
    # Check if the string contains any letters
    if not re.search('[a-zA-Z]', s):
        # If no letters, reverse the string
        return s[::-1]

    # Otherwise, reverse the case of each letter
    result = []
    for char in s:
        if char.isalpha():
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())
        else:
            result.append(char)

    return ''.join(result)

